// This file is generated by AI.

// 侧栏"项目"标签页: 配置 (config.txt 摘要) + 引擎 + 模板。

import { Button } from '@fluentui/react-components';
import { EditRegular, ImageRegular, SettingsRegular } from '@fluentui/react-icons';
import { useEffect, useState } from 'react';

import { requestAlert } from '../confirm';
import { findBinding } from '../lib/bindings';
import { engineLabel, resolveProjectEngine } from '../lib/engine';
import { resolveProjectTemplate, type ProjectTemplateResolution } from '../lib/engineTemplate';
import { fs } from '../lib/fs';
import { gameConfigSummary, parseGameConfigText, type GameConfigSummary } from '../lib/gameConfig';
import { useImageUrl } from '../lib/localImage';
import { joinPath } from '../lib/paths';
import {
  configPathOf,
  openProjectConfig,
  readProjectConfigSummary,
  switchProjectEngine,
  switchTemplate,
} from '../project';
import { useAppStore } from '../state/store';
import { Select, type SelectOption } from './Select';

/** "项目自带"选项的取值: 空串表示不挂引擎层 */
const SELF_CONTAINED = '';

export function ProjectTab() {
  const projectPath = useAppStore((s) => s.projectPath);
  const settings = useAppStore((s) => s.settings);
  const projectBindings = useAppStore((s) => s.projectBindings);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const setSettingsCategory = useAppStore((s) => s.setSettingsCategory);

  const [busy, setBusy] = useState(false);
  const [resolution, setResolution] = useState<ProjectTemplateResolution | null>(null);
  const [summary, setSummary] = useState<GameConfigSummary | null>(null);
  const [hasIndexHtml, setHasIndexHtml] = useState<boolean | null>(null);
  const [reloadToken, setReloadToken] = useState(0);

  const engine = resolveProjectEngine(settings, projectBindings, projectPath);
  const binding = projectPath ? findBinding(projectBindings, projectPath) : undefined;

  /*
   * config.txt 的开着的文档优先。
   *
   * 侧栏显示的是"当前的项目信息", 而用户可能刚在编辑器里改了 `Game_name` 还没存盘 ——
   * 那时磁盘上那份是旧的。订阅文档内容即可实时跟着走 (存盘后内容不变, 因此不会跳)。
   */
  const configPath = projectPath ? configPathOf(projectPath) : null;
  const configContent = useAppStore((s) =>
    configPath ? s.documents.find((doc) => doc.path === configPath)?.content : undefined
  );

  useEffect(() => {
    if (!projectPath) {
      setSummary(null);
      return;
    }
    if (configContent !== undefined) {
      setSummary(gameConfigSummary(parseGameConfigText(configContent)));
      return;
    }
    let cancelled = false;
    void readProjectConfigSummary(projectPath).then((next) => {
      if (!cancelled) setSummary(next);
    });
    return () => {
      cancelled = true;
    };
  }, [projectPath, configContent, reloadToken]);

  // 项目是否自带引擎 (有 index.html 就不需要引擎层)
  useEffect(() => {
    if (!projectPath) {
      setHasIndexHtml(null);
      return;
    }
    let cancelled = false;
    void fs.exists(joinPath(projectPath, 'index.html')).then((stat) => {
      if (!cancelled) setHasIndexHtml(stat.exists && !stat.isDirectory);
    });
    return () => {
      cancelled = true;
    };
  }, [projectPath, reloadToken]);

  useEffect(() => {
    let cancelled = false;
    setResolution(null);
    if (!projectPath) return;
    void resolveProjectTemplate(settings, projectPath).then((next) => {
      if (!cancelled) setResolution(next);
    });
    return () => {
      cancelled = true;
    };
  }, [projectPath, settings, reloadToken]);

  const coverPath =
    projectPath && summary?.titleImg ? joinPath(projectPath, 'game', 'background', summary.titleImg) : null;
  const cover = useImageUrl(coverPath);

  if (!projectPath) return <div className="project-tab empty">未打开项目</div>;

  const template = resolution?.template ?? null;
  const unknownValue = '__project-template-unknown__';
  const templateValue = resolution?.unknownName ? unknownValue : (template?.id ?? '');
  const templateOptions: SelectOption[] = [
    { value: '', label: '跟随引擎默认' },
    ...(resolution?.unknownName ? [{ value: unknownValue, label: resolution.unknownName }] : []),
    ...settings.templates.map((item) => ({ value: item.id, label: item.name })),
  ];
  const engineOptions: SelectOption[] = [
    // 空值不是"没选"的占位, 而是一个真实选项: 项目自己就带一份完整的引擎
    { value: SELF_CONTAINED, label: hasIndexHtml === false ? '未选择引擎' : '项目内置引擎' },
    ...settings.engines.map((item) => ({ value: item.id, label: engineLabel(item) })),
  ];

  const onSwitchTemplate = async (templateId: string) => {
    setBusy(true);
    try {
      if (templateId === unknownValue) return;
      const t = templateId ? (settings.templates.find((x) => x.id === templateId) ?? null) : null;
      await switchTemplate(t ? t.id : null, t ? t.path : null);
      setReloadToken((token) => token + 1);
    } catch (e) {
      requestAlert('切换模板失败', String(e));
    } finally {
      setBusy(false);
    }
  };

  const onSwitchEngine = async (engineId: string) => {
    setBusy(true);
    try {
      await switchProjectEngine(engineId === SELF_CONTAINED ? null : engineId);
    } catch (e) {
      requestAlert('切换引擎失败', String(e));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="project-tab">
      <section className="project-tab-section">
        <span className="settings-label">配置</span>

        <div className="game-info">
          <div className="game-info-cover">
            {cover ? (
              <img src={cover} alt="" draggable={false} />
            ) : (
              <span className="game-info-cover-empty" aria-hidden="true">
                <ImageRegular />
              </span>
            )}
          </div>
          <div className="game-info-fields">
            <div className="game-info-row">
              <span className="game-info-label">名称</span>
              <span className="game-info-value" title={summary?.name || '未设置'}>
                {summary?.name || '未设置'}
              </span>
            </div>
            <div className="game-info-row">
              <span className="game-info-label">标题图</span>
              <span className="game-info-value game-info-key" title={summary?.titleImg || '未设置'}>
                {summary?.titleImg || '未设置'}
              </span>
            </div>

            {/*
              按钮贴在字段列底部、与封面底边对齐 (见 styles.css 的 .game-info):
              这样这一块是一个"封面 + 信息 + 动作"的整块, 不会在右下角留下一行空白。
              识别码不在这里显示: 它是 36 位 UUID, 日常没有可读性, 需要时点"编辑配置"看。
            */}
            <div className="project-tab-actions">
              <Button
                appearance="secondary"
                icon={<EditRegular />}
                onClick={() => void openProjectConfig(projectPath)}
                disabled={busy}
              >
                编辑配置
              </Button>
            </div>
          </div>
        </div>
      </section>

      <section className="project-tab-section">
        <span className="settings-label">引擎</span>
        <div className="project-tab-template-row">
          <Select
            value={binding?.engineId ?? SELF_CONTAINED}
            options={engineOptions}
            disabled={busy}
            onChange={(value) => void onSwitchEngine(value)}
          />
          <Button
            icon={<SettingsRegular />}
            appearance="secondary"
            disabled={busy}
            onClick={() => {
              setSettingsCategory('engine');
              setSettingsOpen(true);
            }}
          >
            管理引擎
          </Button>
        </div>
        {engine ? (
          <span className="project-tab-path" title={engine.path}>
            {engine.path}
          </span>
        ) : hasIndexHtml === false ? (
          <span className="project-tab-warning">项目目录里没有 index.html，请选择一个引擎目录</span>
        ) : (
          <span className="project-tab-path">使用项目内置引擎（index.html）</span>
        )}
      </section>

      <section className="project-tab-section">
        <span className="settings-label">模板</span>
        <div className="project-tab-template-row">
          <Select
            value={templateValue}
            options={templateOptions}
            disabled={busy}
            onChange={(value) => void onSwitchTemplate(value)}
          />
          <Button
            icon={<SettingsRegular />}
            appearance="secondary"
            disabled={busy}
            onClick={() => {
              setSettingsCategory('template');
              setSettingsOpen(true);
            }}
          >
            管理模板
          </Button>
        </div>
        {template ? (
          <span className="project-tab-path" title={template.path}>
            {template.path}
          </span>
        ) : null}
      </section>
    </div>
  );
}
